local WallpaperPrinter = {}
local PRODUCTS = {
    simple_painted_paper = { name = "Preprosto poslikan papir", linenCost = 1, paintCost = 2, time = 3, cost = 40, beauty = 22, happiness = 1, description = "Preprosto poslikan papir za stene." },
    block_printed_wallpaper = { name = "Blokovno tiskana tapeta", linenCost = 2, paintCost = 2, woodCost = 1, time = 6, cost = 130, beauty = 38, happiness = 2, prestige = 2, description = "Blokovno tiskana tapeta za trgovce." },
    silver_striped_wallpaper = { name = "Srebrnopasna tapeta", linenCost = 2, silverCost = 1, paintCost = 2, woodCost = 1, time = 9, cost = 320, beauty = 52, happiness = 2, prestige = 6, description = "Srebrnopasna tapeta za plemiče." },
    gold_leaf_wallpaper = { name = "Zlatolistna tapeta", linenCost = 2, goldCost = 1, silverCost = 1, paintCost = 2, woodCost = 1, time = 13, cost = 760, beauty = 65, happiness = 3, prestige = 14, description = "Zlatolistna tapeta za visoke plemiče." },
    jewel_set_wallpaper = { name = "Draguljasta tapeta", linenCost = 2, goldCost = 1, silverCost = 1, paintCost = 2, woodCost = 1, jewelCost = 1, time = 17, cost = 1700, beauty = 78, happiness = 5, prestige = 27, description = "Tapeta z draguljem za visoko plemstvo." },
    royal_grand_wallpaper = { name = "Kraljevski velika tapeta", linenCost = 3, goldCost = 2, silverCost = 2, paintCost = 3, woodCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 3900, beauty = 92, happiness = 12, prestige = 58, description = "Velika kraljevska tapeta z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    wallpaper_workshop = { name = "Tapetna delavnica", cost = { gold = 240, wood = 120, stone = 100, linen = 6, paint = 6 }, upkeep = 5, qualityBonus = 5 },
    printing_loft = { name = "Tiskarska podstrešje", cost = { gold = 880, wood = 260, stone = 240, silver = 6, paint = 8 }, upkeep = 20, qualityBonus = 18 },
    master_printer_atelier = { name = "Mojstrski tiskarski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_wallpaper_palace = { name = "Kraljevska tapetna palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
WallpaperPrinter.linenStock = 12; WallpaperPrinter.paintStock = 14; WallpaperPrinter.woodStock = 10; WallpaperPrinter.silverStock = 6; WallpaperPrinter.goldStock = 6; WallpaperPrinter.jewelStock = 4; WallpaperPrinter.pearlStock = 4
WallpaperPrinter.productStock = {}; WallpaperPrinter.buildings = {}; WallpaperPrinter.maker = nil; WallpaperPrinter.activeMaking = {}; WallpaperPrinter.totalProducts = 0; WallpaperPrinter.dayTimer = 0
function WallpaperPrinter.init() WallpaperPrinter.linenStock=12; WallpaperPrinter.paintStock=14; WallpaperPrinter.woodStock=10; WallpaperPrinter.silverStock=6; WallpaperPrinter.goldStock=6; WallpaperPrinter.jewelStock=4; WallpaperPrinter.pearlStock=4; WallpaperPrinter.productStock={}; WallpaperPrinter.buildings={}; WallpaperPrinter.maker=nil; WallpaperPrinter.activeMaking={}; WallpaperPrinter.totalProducts=0; WallpaperPrinter.dayTimer=0; print("[WallpaperPrinter] Royal Wallpaper Printer System initialized (6 products, 4 buildings)") end
function WallpaperPrinter.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WallpaperPrinter.maker={name=n or ("Tapetar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tapetar najet: %s (spretnost: %d)",WallpaperPrinter.maker.name,s),"success") end; return true end
function WallpaperPrinter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WallpaperPrinter.build(id) local ok,e=WallpaperPrinter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WallpaperPrinter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WallpaperPrinter.getQualityBonus() local b=0; for _,bd in ipairs(WallpaperPrinter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WallpaperPrinter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.linenCost and WallpaperPrinter.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.paintCost and WallpaperPrinter.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.woodCost and WallpaperPrinter.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and WallpaperPrinter.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WallpaperPrinter.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WallpaperPrinter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WallpaperPrinter.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WallpaperPrinter.buildings==0 then return false,"Potrebna tapetna delavnica" end; if not WallpaperPrinter.maker then return false,"Potreben tapetar" end; return true end
function WallpaperPrinter.make(pt,qty) qty=qty or 1; local ok,e=WallpaperPrinter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.linenCost then WallpaperPrinter.linenStock=WallpaperPrinter.linenStock-d.linenCost*qty end; if d.paintCost then WallpaperPrinter.paintStock=WallpaperPrinter.paintStock-d.paintCost*qty end; if d.woodCost then WallpaperPrinter.woodStock=WallpaperPrinter.woodStock-d.woodCost*qty end; if d.silverCost then WallpaperPrinter.silverStock=WallpaperPrinter.silverStock-d.silverCost*qty end; if d.goldCost then WallpaperPrinter.goldStock=WallpaperPrinter.goldStock-d.goldCost*qty end; if d.jewelCost then WallpaperPrinter.jewelStock=WallpaperPrinter.jewelStock-d.jewelCost*qty end; if d.pearlCost then WallpaperPrinter.pearlStock=WallpaperPrinter.pearlStock-d.pearlCost*qty end; local t=d.time; if WallpaperPrinter.maker then t=math.max(1,t-math.floor(WallpaperPrinter.maker.skill/13)) end; table.insert(WallpaperPrinter.activeMaking,{id="wallpaper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tiskanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WallpaperPrinter.completeMaking(m) local q=1.0+(WallpaperPrinter.getQualityBonus()/100); if WallpaperPrinter.maker then q=q+(WallpaperPrinter.maker.skill/140) end; q=math.min(2.5,q); WallpaperPrinter.productStock[m.productType]=(WallpaperPrinter.productStock[m.productType] or 0)+m.quantity; WallpaperPrinter.totalProducts=WallpaperPrinter.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WallpaperPrinter.maker then WallpaperPrinter.maker.itemsMade=WallpaperPrinter.maker.itemsMade+m.quantity; if math.random()<0.25 then WallpaperPrinter.maker.skill=math.min(100,WallpaperPrinter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tapeta izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"wallpaper.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function WallpaperPrinter.update(dt) if not _G.state then return end; WallpaperPrinter.dayTimer=WallpaperPrinter.dayTimer+dt; if WallpaperPrinter.dayTimer>=30 then WallpaperPrinter.dayTimer=0; for i=#WallpaperPrinter.activeMaking,1,-1 do local m=WallpaperPrinter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WallpaperPrinter.completeMaking(m); table.remove(WallpaperPrinter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WallpaperPrinter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WallpaperPrinter.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WallpaperPrinter.getStats() return {linenStock=WallpaperPrinter.linenStock,paintStock=WallpaperPrinter.paintStock,woodStock=WallpaperPrinter.woodStock,silverStock=WallpaperPrinter.silverStock,goldStock=WallpaperPrinter.goldStock,jewelStock=WallpaperPrinter.jewelStock,pearlStock=WallpaperPrinter.pearlStock,productStock=WallpaperPrinter.productStock,numBuildings=#WallpaperPrinter.buildings,hasMaker=WallpaperPrinter.maker~=nil,makerName=WallpaperPrinter.maker and WallpaperPrinter.maker.name or "—",makerSkill=WallpaperPrinter.maker and WallpaperPrinter.maker.skill or 0,activeMaking=#WallpaperPrinter.activeMaking,totalProducts=WallpaperPrinter.totalProducts} end
return WallpaperPrinter
